import {emptyProject,validateProject,parseProject,saveDefinition,placeInstance,moveInstance,rotateInstance,removeInstance,assemblyIssues,createHistory} from './model.mjs';
const $=id=>document.getElementById(id),teacher=document.body.dataset.role==='teacher',params=new URLSearchParams(location.search);
const clean=(v,fallback)=>/^[a-zA-Z0-9_-]{1,64}$/.test(v||'')?v:fallback;
const session=clean(params.get('session'),'sample'),workspace=clean(params.get('workspace'),session),key=`msv:module-thinking-p1:mc-workshop-1:${session}:${workspace}`,source=crypto.randomUUID();
let project=emptyProject(workspace),mode='build',view,DriveWorld,physics,owner=false,releaseLock,epoch=0,sequence=0,lastSequence=-1,lastEpoch=0,selected=new Set(),snapshot=null,lastSnapshotAt=0,selectedInstance='',canRender=false,thrust=false,brake=false,holding=false,storageProblem=false,importBackup=null;
function feedback(message,error=false){$('feedback').textContent=message;$('feedback').classList.toggle('error',error);}
try{const saved=localStorage.getItem(key);if(saved)project=parseProject(saved,workspace);}catch{storageProblem=true;feedback('保存内容无法读取。当前使用空工作台；原数据未覆盖。可先导出当前作品。',true);}
const history=createHistory(project);let channel;try{channel=new BroadcastChannel(key);}catch{/* storage event fallback */}
function emit(message){const packet={...message,source};if(channel)channel.postMessage(packet);else try{localStorage.setItem(key+':event',JSON.stringify({...packet,nonce:Math.random()}));}catch{feedback('双屏通道不可用；当前只在本窗口操作。请不要把两屏结果当成同步。',true);}}
function publish(){if(owner)emit({type:'state',epoch,sequence:++sequence,project,mode,snapshot});}
function receive(packet){if(!packet||packet.source===source)return;if(packet.type==='hello'){publish();return;}if(owner||packet.type!=='state'||!Number.isSafeInteger(packet.sequence)||!Number.isFinite(packet.epoch))return;
 if(packet.epoch<lastEpoch||(packet.epoch===lastEpoch&&packet.sequence<=lastSequence))return;
 try{const next=validateProject(packet.project);if(!['build','assemble','drive'].includes(packet.mode))return;const changed=JSON.stringify(project)!==JSON.stringify(next)||mode!==packet.mode;project=next;mode=packet.mode;snapshot=packet.snapshot;lastEpoch=packet.epoch;lastSequence=packet.sequence;lastSnapshotAt=performance.now();if(changed)renderUI();if(view&&snapshot)view.pose(snapshot);$('connection').textContent='同场次投屏 · 单一物理结果';updateTelemetry();}catch{/* ignore invalid transport, never evaluate imported data */}
}
if(channel)channel.onmessage=e=>receive(e.data);addEventListener('storage',e=>{if(e.key===key+':event'&&e.newValue)try{receive(JSON.parse(e.newValue));}catch{/* malformed event */}});
function persist(){try{localStorage.setItem(key,JSON.stringify(project));storageProblem=false;$('storage-warning').textContent='';return true;}catch{storageProblem=true;$('storage-warning').textContent='⚠ 保存失败：作品仍在内存，请立即导出 JSON。';feedback('浏览器保存失败或容量不足；当前作品仍在内存，请立即导出 JSON。',true);return false;}}
function commit(next){if(!owner)return;const valid=validateProject(next);history.apply(valid);project=valid;snapshot=null;physics?.dispose();physics=null;if(mode==='drive')mode='assemble';persist();renderUI();publish();}
function act(work){if(!owner)return feedback('当前为观看窗口。请在唯一教师操作窗口完成拼装。',true);try{work();}catch(e){feedback('没有修改作品：'+(e.message||'操作无效')+'。请检查配方、选择和接口。',true);}}
const blockKey=b=>`${b.x},${b.y},${b.z}`;
function editBlock(coord){act(()=>{if(mode!=='build')return;const tool=$('tool').value,k=blockKey(coord),existing=project.blocks.find(b=>blockKey(b)===k);if(tool==='camera')return feedback('相机模式不会放方块；请切换到「放置」。');if(tool==='select'){if(existing){if(selected.has(k))selected.delete(k);else selected.add(k);renderUI();}return;}const next=structuredClone(project);if(tool==='erase'){next.blocks=next.blocks.filter(b=>blockKey(b)!==k);selected.delete(k);}else{if(existing)return feedback('这里已经有方块，先删除再放置。');next.blocks.push({x:coord.x,y:coord.y,z:coord.z,material:$('material').value});}commit(next);feedback(tool==='erase'?'方块已删除，可撤销。':'方块已放置。选择组合后保存为模块。');});}
for(let z=-4;z<=4;z++){const o=document.createElement('option');o.value=z;o.textContent=z;$('layer').append(o);}$('layer').value='0';
function options(select,items){const value=select.value;select.replaceChildren();for(const [id,label]of items){const o=document.createElement('option');o.value=id;o.textContent=label;select.append(o);}if(items.some(([id])=>id===value))select.value=value;}
const socketNames={'wheel-fl':'前左轮','wheel-fr':'前右轮','wheel-rl':'后左轮','wheel-rr':'后右轮',engine:'推进器'};
function renderUI(){
 $('mode-label').textContent={build:'搭方块',assemble:'装小车',drive:'物理试驾'}[mode];$('build-tools').hidden=mode!=='build';$('library').hidden=mode==='drive';$('drive-controls').hidden=mode!=='drive';
 for(const b of document.querySelectorAll('[data-mode]')){b.classList.toggle('active',b.dataset.mode===mode);b.disabled=!owner||(!canRender&&b.dataset.mode==='drive');}
 for(const node of document.querySelectorAll('[data-author] button,[data-author] input,[data-author] select,button[data-author]'))if(!['claim','open-screen'].includes(node.id))node.disabled=!owner;
 const z=Number($('layer').value);$('block-grid').replaceChildren();for(let y=4;y>=0;y--)for(let x=-4;x<=4;x++){const b=document.createElement('button'),c={x,y,z},k=blockKey(c),existing=project.blocks.find(n=>blockKey(n)===k);b.type='button';b.setAttribute('aria-label',`方块 X${x} Y${y} Z${z}`);b.textContent=existing?{rubber:'橡',metal:'金',fuel:'燃'}[existing.material]:'·';if(existing)b.dataset.material=existing.material;b.classList.toggle('selected',selected.has(k));b.disabled=!owner;b.onclick=()=>editBlock(c);$('block-grid').append(b);}
 $('selection-info').textContent=`已选 ${project.blocks.filter(b=>selected.has(blockKey(b))).length} 块 / 工作台 ${project.blocks.length} 块。先选中要保存的组合。`;
 options($('definition'),project.definitions.map(d=>[d.id,d.name]));showDefinition();options($('instance'),project.instances.map(i=>[i.id,`${socketNames[i.socket]} · ${project.definitions.find(d=>d.id===i.definitionId).name} · ${i.rotation}°`]));if(project.instances.some(i=>i.id===selectedInstance))$('instance').value=selectedInstance;
 const issues=assemblyIssues(project);$('assembly-info').textContent=issues.length?'还缺：'+issues.map(i=>i.replace(/wheel-fl|wheel-fr|wheel-rl|wheel-rr|engine/g,s=>socketNames[s])).join('、'):'四个轮子＋一个推进器已连接；可以进入试驾。';
 view?.setProject(project,mode,selected,$('instance').value);if(snapshot)view?.pose(snapshot);updateTelemetry();
}
function showDefinition(){const d=project.definitions.find(d=>d.id===$('definition').value);$('definition-info').textContent=d?`${d.responsibility} · ${d.blocks.length} 块 · ${d.blocks.map(b=>({rubber:'橡胶',metal:'金属',fuel:'虚拟燃料'})[b.material]).join('＋')}`:'先搭方块并保存模块。';}
$('definition').onchange=showDefinition;$('instance').onchange=()=>{selectedInstance=$('instance').value;renderUI();};$('layer').onchange=renderUI;
$('tool').onchange=()=>{view?.editMode($('tool').value);feedback('已切换工具：'+$('tool').selectedOptions[0].textContent);};
$('camera').onclick=()=>{$('tool').value='camera';view?.editMode('camera');feedback('左键／单指旋转，右键／双指平移，滚轮／双指缩放。');};$('home').onclick=()=>view?.home();$('follow').onchange=()=>{if(view){view.follow=$('follow').checked;view.lastTarget=null;}};
$('select-all').onclick=()=>act(()=>{selected=new Set(project.blocks.map(blockKey));renderUI();});$('clear-blocks').onclick=()=>act(()=>{selected.clear();commit({...project,blocks:[]});feedback('只清空工作台，模块库和小车保持不变；可撤销。');});
for(const action of ['undo','redo'])$(action).onclick=()=>act(()=>{physics?.dispose();physics=null;snapshot=null;if(mode==='drive')mode='assemble';project=history[action]();selected.clear();persist();renderUI();publish();feedback(action==='undo'?'已撤销。':'已重做。');});
$('save-module').onsubmit=e=>{e.preventDefault();act(()=>{const blocks=project.blocks.filter(b=>selected.has(blockKey(b)));if(!blocks.length)throw Error('先选择要保存的方块');commit(saveDefinition(project,{id:crypto.randomUUID(),name:$('module-name').value.trim(),responsibility:$('responsibility').value.trim(),behavior:$('behavior').value,blocks}));$('definition').value=project.definitions.at(-1).id;showDefinition();feedback('模块已保存。模块库里是你选中的真实组合，可重复装配。');});};
$('load-definition').onclick=()=>act(()=>{const d=project.definitions.find(d=>d.id===$('definition').value);if(!d)throw Error('模块库为空');mode='build';selected=new Set(d.blocks.map(blockKey));commit({...project,blocks:structuredClone(d.blocks)});feedback('已复制内部方块到工作台；编辑不会改掉已有定义或实例。');});
$('place-module').onclick=()=>act(()=>{const id=crypto.randomUUID();const next=placeInstance(project,{id,definitionId:$('definition').value,socket:$('socket').value});mode='assemble';commit(next);selectedInstance=id;renderUI();feedback('连接成功：一个独立实例已吸附到接口。');});
$('move-instance').onclick=()=>act(()=>{commit(moveInstance(project,$('instance').value,$('socket').value));feedback('整体移动完成，其他实例和原定义不变。');});$('rotate-instance').onclick=()=>act(()=>{commit(rotateInstance(project,$('instance').value));feedback('此实例已转向；推进器按箭头方向施力，其他实例不变。');});$('delete-instance').onclick=()=>act(()=>{commit(removeInstance(project,$('instance').value));feedback('已拆下此实例，原模块还在模块库。');});
function switchMode(next){act(()=>{if(next==='drive'){const issues=assemblyIssues(project);if(issues.length)throw Error('请先接好四个轮子和一个推进器');if(!DriveWorld||!canRender)throw Error('三维或物理引擎尚未就绪');physics?.dispose();physics=new DriveWorld(project);snapshot=physics.snapshot();}else{physics?.dispose();physics=null;snapshot=null;}mode=next;stopInput();renderUI();view?.home();publish();feedback(next==='drive'?'按住推进试一次；路线包含平地、坡、起伏和橙色标杆处落差。':'回到拼装可调整方向或连接，然后从同一起点复测。');});}
for(const b of document.querySelectorAll('[data-mode]'))b.onclick=()=>switchMode(b.dataset.mode);
function stopInput(){thrust=brake=false;holding=false;$('thrust').classList.remove('pressed');$('brake').classList.remove('pressed');}
for(const [id,set]of [['thrust',v=>thrust=v],['brake',v=>brake=v]]){const b=$(id);b.onpointerdown=e=>{if(!owner||mode!=='drive')return;e.preventDefault();b.setPointerCapture(e.pointerId);holding=true;set(true);b.classList.add('pressed');};b.onpointerup=b.onpointercancel=()=>{set(false);b.classList.remove('pressed');holding=false;};b.onlostpointercapture=()=>{set(false);b.classList.remove('pressed');};b.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();e.stopPropagation();if(owner&&mode==='drive')set(true);}};b.onkeyup=()=>set(false);}
$('workspace').addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT','BUTTON'].includes(e.target.tagName))return;if(mode==='drive'&&owner&&['ArrowUp','ArrowDown',' '].includes(e.key)){e.preventDefault();e.stopPropagation();holding=true;if(e.key==='ArrowUp')thrust=true;else brake=true;}});addEventListener('keyup',e=>{if(['ArrowUp','ArrowDown',' '].includes(e.key))stopInput();});addEventListener('blur',()=>{stopInput();physics?.pause();});document.addEventListener('visibilitychange',()=>{stopInput();physics?.pause();last=performance.now();});
$('reset-car').onclick=()=>act(()=>{if(physics){stopInput();physics.reset();snapshot=physics.snapshot();view?.pose(snapshot);view?.home();publish();feedback('同一辆车回到同一起点。方向和模块没有被替换。');}});
$('expand').onclick=()=>{const expanded=$('workspace').classList.toggle('expanded');$('expand').textContent=expanded?'收起展示区':'展开展示区';};$('fullscreen').onclick=async()=>{try{await $('workspace').requestFullscreen();}catch{feedback('浏览器未允许全屏，请使用「展开展示区」。',true);}};$('exit-full').onclick=()=>document.exitFullscreen();
$('save-project').onclick=()=>{if(owner&&persist())feedback('已保存到此浏览器／此设备。换设备请导出 JSON。');};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`mc-workshop-${workspace}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);feedback('已导出模块定义、方块和当前装配实例。');};
$('import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(!owner)throw Error('观看窗口不能导入');if(file.size>102400)throw Error('文件最多100KB');const text=await file.text(),next=parseProject(text,workspace);importBackup={name:file.name,text};mode='build';selected.clear();commit(next);feedback('导入成功，可撤销回到导入前；原始文件没有改动。');}catch(error){feedback('导入失败，当前作品未改变：'+error.message,true);}finally{e.target.value='';}};
$('open-screen').onclick=()=>{const url=new URL('../audience/index.html',location.href);url.searchParams.set('session',session);url.searchParams.set('workspace',workspace);const w=window.open(url,'msv-mc-'+session+'-'+workspace);if(!w)feedback('投屏窗口被拦截，请允许本站弹窗。',true);};
async function claim(){if(!teacher||owner)return;if(!navigator.locks){feedback('此浏览器不支持安全操作锁；请使用新版 Chrome / Edge / Safari。不会开启第二份独立模拟。',true);return;}navigator.locks.request(key+':owner',{ifAvailable:true},async lock=>{if(!lock){$('connection').textContent='另一教师窗口正在操作 · 当前只读';renderUI();emit({type:'hello'});return;}owner=true;epoch=Date.now();sequence=0;$('connection').textContent='教师操作源 · 此设备自动保存';renderUI();publish();await new Promise(resolve=>releaseLock=resolve);});}
$('claim').onclick=claim;addEventListener('pagehide',()=>{stopInput();releaseLock?.();});
function updateTelemetry(){if(snapshot){$('telemetry').textContent=`${owner?'真实物理':'投屏快照'} · ${snapshot.time.toFixed(1)} 秒 · 速度 ${snapshot.speed.toFixed(1)} · 位置 X ${snapshot.chassis.p.x.toFixed(1)} / 高度 ${snapshot.chassis.p.y.toFixed(1)}${snapshot.outOfBounds?' · 已离开试驾区，请重置':''}`;}else $('telemetry').textContent=`工作区 ${workspace} · ${project.blocks.length} 个工作台方块 · ${project.definitions.length} 个定义 · ${project.instances.length} 个实例`;}
let last=performance.now(),lastSend=0;
function frame(now){const delta=(now-last)/1000;last=now;if(owner&&physics&&!document.hidden){if(!snapshot?.outOfBounds){snapshot=physics.advance(delta,{thrust,brake});view?.pose(snapshot);}else stopInput();if(now-lastSend>50){publish();updateTelemetry();lastSend=now;}}if(!owner&&now-lastSnapshotAt>3500)$('connection').textContent='等待教师操作源 · 未独立运行物理';view?.render();requestAnimationFrame(frame);}
async function boot(){try{const [{WorkshopView},physical]=await Promise.all([import('./render.mjs'),import('./physics.mjs')]);await physical.initPhysics();DriveWorld=physical.DriveWorld;view=new WorkshopView($('canvas'),editBlock);canRender=true;renderUI();view.home();if(!storageProblem)feedback(teacher?'先选择材料和放置工具，在网格上搭五个橡胶方块。':'观看教师正在搭建的同一件作品；相机可自行观察。');}catch{$('fallback').hidden=false;canRender=false;renderUI();feedback('三维／物理不可用：未进入试驾；请重试或用静态说明讲解。',true);}}
addEventListener('msv-workshop-render-failed',()=>{stopInput();physics?.dispose();physics=null;snapshot=null;canRender=false;$('fallback').hidden=false;renderUI();feedback('三维上下文已丢失，试驾已停止；作品保留，可导出后重试。',true);});
$('retry').onclick=()=>location.reload();renderUI();claim();emit({type:'hello'});boot();requestAnimationFrame(frame);
// Diagnostics expose data, not a second control path; browser tests use real controls.
window.MSVWorkshop={inspect:()=>({project:structuredClone(project),mode,owner,snapshot:structuredClone(snapshot),selected:[...selected],storageProblem,holding,importBackup:importBackup?.name??null,canvas:view?{width:view.renderer.domElement.width,height:view.renderer.domElement.height,camera:view.camera.position.toArray()}:null,epoch,sequence,lastSequence}),forceStorageCheck:persist};
